pub const GLYPH_WIDTH: i32 = 10;
pub const GLYPH_HEIGHT: i32 = 16;

#[derive(Clone)]
pub struct RasterizedGlyph {
    pub width: usize,
    pub height: usize,
    pub xmin: i32,
    pub ymin: i32,
    pub advance: i32,
    pub bitmap: Vec<u8>,
}

const MAX_UI_GLYPH_CACHE: usize = 1536;

lazy_static! {
    static ref UI_VECTOR_FONT: Option<fontdue::Font> = if !UI_FONT_BYTES.is_empty() {
        fontdue::Font::from_bytes(UI_FONT_BYTES, fontdue::FontSettings::default()).ok()
    } else {
        None
    };
    static ref UI_GLYPH_CACHE: Mutex<BTreeMap<(char, u16, bool), RasterizedGlyph>> =
        Mutex::new(BTreeMap::new());
}

#[inline(always)]
fn round_f32_i32(v: f32) -> i32 {
    if v >= 0.0 {
        (v + 0.5) as i32
    } else {
        (v - 0.5) as i32
    }
}

