#[inline]
pub fn lookup_glyph(ch: char) -> (&'static [u8; 160], i32) {
    let code = ch as u32;
    if (0x20..=0x7E).contains(&code) {
        let idx = (code - 0x20) as usize;
        return (&FONT_UI_ATLAS[idx], FONT_UI_ADVANCES[idx] as i32);
    }
    if let Some(found) = super::font_cyrillic::lookup_extra_glyph(ch, false) {
        return found;
    }
    let idx = ('?' as u32 - 0x20) as usize;
    (&FONT_UI_ATLAS[idx], FONT_UI_ADVANCES[idx] as i32)
}

#[inline]
pub fn lookup_glyph_bold(ch: char) -> (&'static [u8; 160], i32) {
    let code = ch as u32;
    if (0x20..=0x7E).contains(&code) {
        let idx = (code - 0x20) as usize;
        return (&FONT_UI_BOLD_ATLAS[idx], FONT_UI_BOLD_ADVANCES[idx] as i32);
    }
    if let Some(found) = super::font_cyrillic::lookup_extra_glyph(ch, true) {
        return found;
    }
    let idx = ('?' as u32 - 0x20) as usize;
    (&FONT_UI_BOLD_ATLAS[idx], FONT_UI_BOLD_ADVANCES[idx] as i32)
}

fn ensure_ui_cached<'a>(
    cache: &'a mut BTreeMap<(char, u16, bool), RasterizedGlyph>,
    ch: char,
    px_size: u16,
    bold: bool,
) -> Option<&'a RasterizedGlyph> {
    let px = px_size.clamp(8, 64);
    let key = (ch, px, bold);
    if cache.contains_key(&key) {
        return cache.get(&key);
    }
    let font = UI_VECTOR_FONT.as_ref()?;
    if ch != ' ' && font.lookup_glyph_index(ch) == 0 {
        return None;
    }
    let (metrics, mut bitmap) = font.rasterize(ch, px as f32);
    let mut w = metrics.width;
    let h = metrics.height;
    let mut adv = round_f32_i32(metrics.advance_width).max(if ch == ' ' { 3 } else { 1 });

    // Subtle geometric weight synthesis when only a regular TTF is embedded
    if bold && w > 0 && h > 0 {
        let new_w = w + 1;
        let mut bold_bmp = Vec::with_capacity(new_w * h);
        for row in 0..h {
            let src = &bitmap[row * w..(row + 1) * w];
            for col in 0..new_w {
                let c0 = if col < w { src[col] } else { 0 };
                let c_prev = if col > 0 { (src[col - 1] as u16 * 168) >> 8 } else { 0 };
                bold_bmp.push(c0.max(c_prev.min(255) as u8));
            }
        }
        bitmap = bold_bmp;
        w = new_w;
        if px >= 11 && ch != ' ' {
            adv += 1;
        }
    }

    if cache.len() >= MAX_UI_GLYPH_CACHE {
        cache.clear();
    }
    cache.insert(
        key,
        RasterizedGlyph {
            width: w,
            height: h,
            xmin: metrics.xmin,
            ymin: metrics.ymin,
            advance: adv,
            bitmap,
        },
    );
    cache.get(&key)
}

pub fn with_ui_glyph<R>(
    ch: char,
    px_size: u16,
    bold: bool,
    f: impl FnOnce(&RasterizedGlyph) -> R,
) -> Option<R> {
    let mut cache = UI_GLYPH_CACHE.lock();
    let g = ensure_ui_cached(&mut cache, ch, px_size, bold)?;
    Some(f(g))
}

pub fn rasterize_ui_glyph(ch: char, px_size: u16, bold: bool) -> Option<RasterizedGlyph> {
    with_ui_glyph(ch, px_size, bold, |g| g.clone())
}

pub fn ui_glyph_advance(ch: char, px_size: u16, bold: bool) -> Option<i32> {
    with_ui_glyph(ch, px_size, bold, |g| g.advance)
}

